import { test, expect } from '@playwright/test';

test.describe('Table Row Numbers', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/your-table-page-url');
  });

  test('should display row numbers in the first column', async ({ page }) => {
    const rows = await page.locator('table tbody tr').count();
    for (let i = 0; i < rows; i++) {
      const rowNumber = await page.locator(`table tbody tr:nth-child(${i + 1}) td:first-child`).innerText();
      expect(rowNumber).toBe((i + 1).toString());
    }
  });

  test('should have correct row numbers after adding a new row', async ({ page }) => {
    await page.getByRole('button', { name: 'Add Row' }).click();
    const rows = await page.locator('table tbody tr').count();
    for (let i = 0; i < rows; i++) {
      const rowNumber = await page.locator(`table tbody tr:nth-child(${i + 1}) td:first-child`).innerText();
      expect(rowNumber).toBe((i + 1).toString());
    }
  });
});
